begin;
do $test$
declare actor uuid;worker uuid;item_a uuid:=gen_random_uuid();item_b uuid:=gen_random_uuid();station text:='RTIME-'||substr(gen_random_uuid()::text,1,8);r public.production_live_runs;r2 public.production_live_runs;first_id uuid:=gen_random_uuid();late_id uuid:=gen_random_uuid();middle_id uuid:=gen_random_uuid();batch_a uuid:=gen_random_uuid();batch_b uuid:=gen_random_uuid();payload jsonb;submitted timestamptz;start_at timestamptz:=date_trunc('minute',clock_timestamp()-interval '6 hours');daily_id uuid;day text;begin
 select a.user_id into actor from public.global_system_admins a join public.operadores o on o.uid=a.user_id where o.activo limit 1;
 select m.user_id into worker from public.global_department_memberships m join public.operadores o on o.uid=m.user_id where m.department='production' and m.active and m.role='operador' and o.activo limit 1;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 insert into public.inventory_items(id,part_number,category) values(item_a,'RTIME-A-'||item_a,'SEMI'),(item_b,'RTIME-B-'||item_b,'SEMI');
 insert into public.inventory_workstations(code,name,machine_type,materials) values(station,'Report time fixture',(select name from public.machine_types limit 1),jsonb_build_array(jsonb_build_object('item_ids',jsonb_build_array(item_a,item_b))));
 perform public.production_shift_plan(jsonb_build_object('id',gen_random_uuid(),'started_at',start_at,'shift_hours',8,'stations',jsonb_build_array(jsonb_build_object('station_code',station,'item_ids',jsonb_build_array(item_a,item_b)))));
 select * into r from public.production_live_runs where station_code=station and item_id=item_a;select * into r2 from public.production_live_runs where station_code=station and item_id=item_b;
 update public.production_live_runs set shift_target=750,pieces_per_hour=100 where id in(r.id,r2.id);
 perform public.production_live_action('checkpoint',jsonb_build_object('id',first_id,'run_id',r.id,'quantity',100,'recorded_at',start_at+interval '1 hour'));
 perform public.production_live_action('checkpoint',jsonb_build_object('id',late_id,'run_id',r.id,'quantity',300,'recorded_at',start_at+interval '3 hours'));
 payload:=jsonb_build_object('id',middle_id,'run_id',r.id,'quantity',200,'recorded_at',start_at+interval '2 hours');perform public.production_live_action('checkpoint',payload);perform public.production_live_action('checkpoint',payload);
 select submitted_at into submitted from public.production_checkpoints where id=middle_id;
 if not exists(select 1 from public.production_checkpoints where id=middle_id and recorded_at=start_at+interval '2 hours' and submitted_at>recorded_at and quantity=200 and expected_quantity>0) or (select count(*) from public.production_checkpoints where run_id=r.id)<>3 or not exists(select 1 from public.production_live_runs where id=r.id and latest_quantity=300 and latest_at=start_at+interval '3 hours') then raise exception 'late capture changed chronology/audit/quantities';end if;
 begin perform public.production_live_action('checkpoint',jsonb_build_object('id',gen_random_uuid(),'run_id',r.id,'quantity',400,'recorded_at',start_at+interval '90 minutes'));raise exception 'nonmonotonic backdate accepted';exception when others then if sqlerrm<>'pl_quantity_invalid' then raise;end if;end;
 begin perform public.production_live_action('checkpoint',jsonb_build_object('id',gen_random_uuid(),'run_id',r.id,'quantity',400,'recorded_at',clock_timestamp()+interval '1 hour'));raise exception 'future accepted';exception when others then if sqlerrm<>'rp_time_invalid' then raise;end if;end;
 begin perform public.production_live_action('checkpoint',jsonb_build_object('id',gen_random_uuid(),'run_id',r.id,'quantity',0,'recorded_at',start_at-interval '1 hour'));raise exception 'before start accepted';exception when others then if sqlerrm<>'rp_time_invalid' then raise;end if;end;
 begin perform public.production_live_action('checkpoint',jsonb_build_object('id',gen_random_uuid(),'run_id',r.id,'quantity',200,'recorded_at',start_at+interval '2 hours'));raise exception 'duplicate time accepted';exception when others then if sqlerrm<>'rp_time_exists' then raise;end if;end;
 perform public.production_live_action('edit_checkpoint',jsonb_build_object('id',middle_id,'quantity',250,'recorded_at',start_at+interval '150 minutes'));
 if not exists(select 1 from public.production_checkpoints where id=middle_id and recorded_at=start_at+interval '150 minutes' and quantity=250 and submitted_at=submitted) then raise exception 'edit time lost capture audit';end if;
 begin perform public.production_live_action('edit_checkpoint',jsonb_build_object('id',middle_id,'quantity',350,'recorded_at',start_at+interval '150 minutes'));raise exception 'edit nonmonotonic accepted';exception when others then if sqlerrm<>'pl_quantity_invalid' then raise;end if;end;
 payload:=jsonb_build_object('products',jsonb_build_array(jsonb_build_object('id',batch_a,'run_id',r.id,'item_id',item_a,'quantity',400,'recorded_at',start_at+interval '4 hours'),jsonb_build_object('id',batch_b,'run_id',r2.id,'item_id',item_b,'quantity',200,'recorded_at',start_at+interval '4 hours')));perform public.production_live_action('checkpoint_batch',payload);perform public.production_live_action('checkpoint_batch',payload);
 if (select count(*) from public.production_checkpoints where id in(batch_a,batch_b) and recorded_at=start_at+interval '4 hours' and submitted_at>recorded_at)<>2 then raise exception 'batch lost effective/capture clocks';end if;
 perform public.production_live_action('finish',jsonb_build_object('id',gen_random_uuid(),'run_id',r.id,'quantity',500,'finished_at',start_at+interval '5 hours','timezone','UTC'));
 begin perform public.production_live_action('edit_checkpoint',jsonb_build_object('id',(select id from public.production_checkpoints where run_id=r.id and recorded_at=start_at+interval '5 hours'),'quantity',500,'recorded_at',start_at+interval '290 minutes'));raise exception 'final time changed without closure';exception when others then if sqlerrm<>'rp_final_locked' then raise;end if;end;
 select id into daily_id from public.production_station_reports where live_run_id=r.id and status='draft';day:=(start_at at time zone 'UTC')::date::text;
 perform public.production_station_action('save',jsonb_build_object('id',daily_id,'live_run_id',r.id,'station_code',station,'item_id',item_a,'production_date',day,'start_time',to_char(start_at at time zone 'UTC','HH24:MI'),'end_time',to_char((start_at+interval '5 hours') at time zone 'UTC','HH24:MI'),'ends_next_day',(start_at at time zone 'UTC')::date<>((start_at+interval '5 hours') at time zone 'UTC')::date,'people',1,'machine_quantity',500,'scrap_quantity',0,'rework_quantity',0,'full_boxes',0,'pallets',0,'pieces_per_box',0,'report_mode','production','downtime_events','[]'::jsonb,'timezone','UTC'));
 if not exists(select 1 from public.production_station_reports where id=daily_id and end_time=to_char((start_at+interval '5 hours') at time zone 'UTC','HH24:MI')::time and created_at>start_at+interval '5 hours') then raise exception 'daily production cutoff/capture clock failed';end if;
 perform set_config('request.jwt.claim.sub',worker::text,true);
 begin perform public.production_live_action('edit_checkpoint',jsonb_build_object('id',middle_id,'quantity',250,'recorded_at',start_at+interval '140 minutes'));raise exception 'unauthorized history time edit';exception when others then if sqlerrm not in('pr_forbidden','ra_denied') then raise;end if;end;
end $test$;
rollback;
